from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')

def _to_cents(value):
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)

def invoice(lines, tax_rate):
    rounded_lines = [_to_cents(Decimal(row['unit_price']) * row['qty']) for row in lines]
    subtotal = sum(rounded_lines, Decimal('0.00'))
    tax = sum(
        (_to_cents(line * Decimal(tax_rate)) for line, row in zip(rounded_lines, lines) if row['taxable']),
        Decimal('0.00'),
    )
    total = subtotal + tax
    return {
        'subtotal': f'{subtotal:.2f}',
        'tax': f'{tax:.2f}',
        'total': f'{total:.2f}',
    }
